def test_provider_parse_greenhouse() -> None:
    p, site, pid = _ats_provider_from_url("https://boards.greenhouse.io/acme/jobs/123456")
    assert (p, site, pid) == ("greenhouse", "acme", "123456")


def test_provider_parse_ashby_and_lever() -> None:
    assert _ats_provider_from_url("https://jobs.ashbyhq.com/reducto/abc-uuid")[0] == "ashby"
    assert _ats_provider_from_url("https://jobs.lever.co/fleet/def-uuid")[0] == "lever"


def test_provider_parse_unknown() -> None:
    p, site, _ = _ats_provider_from_url("https://careers.example.com/apply/9")
    assert p == "unknown"
    assert site == "careers.example.com"


def test_field_type_sensitive_and_kinds() -> None:
    assert _ats_field_type("Are you legally authorized to work?", "select", "", True) == "work_authorization"
    assert _ats_field_type("Gender", "select", "", True) == "self_identification"
    assert _ats_field_type("Resume/CV", "input", "file", False) == "file"
    assert _ats_field_type("Cover letter", "textarea", "", False) == "free_text"
    assert _ats_field_type("Preferred location", "select", "", True) == "choice"
    assert _ats_field_type("Email", "input", "email", False) == "email"
    assert _ats_field_type("First name", "input", "text", False) == "text"


def test_generic_form_from_dom_shape() -> None:
    rows = [
        {"tag": "input", "type": "text", "id": "first_name", "label": "First name", "required": True},
        {"tag": "input", "type": "file", "id": "resume", "label": "Resume/CV *", "required": True},
        {"tag": "textarea", "type": "", "id": "q1", "label": "Why here?", "required": False},
        {"tag": "select", "type": "", "id": "auth", "label": "Work authorization", "required": True, "options": ["Yes", "No"]},
        {"tag": "input", "type": "text", "id": "dupe", "label": "First name", "required": True},  # dedup
    ]
    form = _generic_form_from_dom("greenhouse", "acme", "123", "https://x/apply", rows)
    assert form["provider"] == "greenhouse"
    names = [f["name"] for f in form["fields"]]
    assert names == ["First name", "Resume/CV", "Why here?", "Work authorization"]  # trimmed + deduped
    assert "Resume/CV" in form["accepted_attachments"]
    auth = next(f for f in form["fields"] if f["name"] == "Work authorization")
    assert auth["field_type"] == "work_authorization"
    assert auth["required"] is True


def test_generic_form_from_dom_empty_raises() -> None:
    with pytest.raises(BrowserCaptureError):
        _generic_form_from_dom("unknown", "x", "1", "u", [{"tag": "input", "label": ""}])


def test_meetup_capture_wall_clock_timeout_writes_failed_receipt(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setenv("MONITOR_MEETUP_CAPTURE_TIMEOUT_SECONDS", "1")
    monkeypatch.setattr(browser_capture, "ensure_browser", lambda _surf_run: "existing")

    def slow_surf(*_: object, **__: object) -> str:
        time.sleep(2)
        return "123: tab"

    monkeypatch.setattr(browser_capture, "_surf", slow_surf)

    receipt = capture_meetup_buffalo(tmp_path)

    assert receipt["status"] == "FAILED"
    assert "Meetup Buffalo capture exceeded 1s" in receipt["error"]
    assert receipt["evidence_path"] is None
    stored = json.loads((tmp_path / "meetup-capture-receipt.json").read_text(encoding="utf-8"))
    assert stored["status"] == "FAILED"


def test_surf_pause_reraises_capture_wall_clock_timeout(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    def alarm_timeout(*_: object, **__: object) -> str:
        raise TimeoutError("Meetup Buffalo capture exceeded 1s")

    monkeypatch.setattr(browser_capture, "_surf", alarm_timeout)

    with pytest.raises(TimeoutError, match="Meetup Buffalo capture exceeded 1s"):
        browser_capture._surf_pause(Path("surf/run.sh"), "1")


def test_isolated_meetup_capture_terminates_wedged_child(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    def wedged_capture(*_: object, **__: object) -> dict[str, object]:
        time.sleep(10)
        return {"status": "OK"}

    monkeypatch.setattr(browser_capture, "capture_meetup_buffalo", wedged_capture)

    started = time.monotonic()
    receipt = capture_meetup_buffalo_isolated(tmp_path, timeout_seconds=1)

    assert time.monotonic() - started < 5
    assert receipt["status"] == "FAILED"
    assert "isolated timeout 1s" in receipt["error"]
    assert receipt["blocked_by_systemic_failure"] is True
    assert receipt["failure_signature"] == "meetup_isolated_capture_timeout"
    assert receipt["group_capture_skipped"] == 12
    stored = json.loads((tmp_path / "meetup-capture-receipt.json").read_text(encoding="utf-8"))
    assert stored["status"] == "FAILED"
    assert stored["blocked_by_systemic_failure"] is True


def test_meetup_group_capture_circuit_breaks_repeated_timeouts(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(browser_capture, "ensure_browser", lambda _surf_run: "existing")
    monkeypatch.setenv("MONITOR_MEETUP_MAX_GROUP_FAILURES", "3")
    group_urls = [
        f"https://www.meetup.com/group-{idx}/"
        for idx in range(5)
    ]

    def fake_surf(_surf_run: Path, *args: str, timeout: int = 90) -> str:
        del _surf_run, timeout
        if args[0] == "tab.new":
            return "123: tab"
        if args[0] == "wait":
            return ""
        if args[0] == "tab.close":
            return ""
        if args[0] == "js":
            script = args[-1]
            if "find/?source=GROUPS" not in script:
                raise subprocess.TimeoutExpired(args, 20)
            return "NAV"
        raise AssertionError(f"unexpected surf args: {args!r}")

    def fake_snapshot(_surf_run: Path, _tab_id: str) -> dict[str, object]:
        return {
            "title": "Search groups",
            "text": "Buffalo groups",
            "links": group_urls,
        }

    monkeypatch.setattr(browser_capture, "_surf", fake_surf)
    monkeypatch.setattr(browser_capture, "_surf_pause", lambda *args, **kwargs: None)
    monkeypatch.setattr(browser_capture, "_meetup_page_snapshot", fake_snapshot)

    receipt = capture_meetup_buffalo(tmp_path, max_group_pages=5)

    assert receipt["group_capture_failed"] == 3
    assert receipt["group_capture_skipped"] == 2
    assert receipt["blocked_by_systemic_failure"] is True
    assert receipt["failure_signature"] == "meetup_group_detail_capture_failed"
    evidence = json.loads((tmp_path / "meetup-buffalo-evidence.json").read_text(encoding="utf-8"))
    assert evidence["blocked_by_systemic_failure"] is True
    assert len(evidence["group_capture_failures"]) == 3
    assert len(evidence["skipped_group_urls"]) == 2
